    missing.push('--b');
  }

  if (missing.length === 0) {
    return null;
  }

  return `the following arguments are required: ${missing.join(', ')}`;
}

export function parseCommandLine(argv) {
  const programName = getProgramName(argv[1]);
  const tokens = argv.slice(2);
  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        output: buildHelp(programName),
      };
    }

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
