    if (token.startsWith('--b=')) {
      values.b = token.slice(4);
      continue;
    }

    if (token === '--a' || token === '--b') {
      const nextToken = tokens[index + 1];

      if (isMissingValueToken(nextToken)) {
        return {
          kind: 'error',
          code: 2,
          output: buildError(programName, `argument ${token}: expected one argument`),
        };
      }

      values[token.slice(2)] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const requiredMessage = buildRequiredMessage(values);

  if (requiredMessage !== null) {
    return {
      kind: 'error',
      code: 2,
      output: buildError(programName, requiredMessage),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      code: 2,
      output: buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'values',
    values,
  };
