import { CHECKSUM_LENGTH, FINAL_CONSTANT } from './constants.mjs';
import { expandHrp } from './hrp.mjs';
import { polymod } from './polymod.mjs';

export function bech32CreateChecksum(hrp, data) {
  const values = [...expandHrp(hrp), ...data];
  const padding = new Array(CHECKSUM_LENGTH).fill(0);
  const checksumValue = polymod([...values, ...padding]) ^ FINAL_CONSTANT;
  const checksum = [];

  for (let index = 0; index < CHECKSUM_LENGTH; index += 1) {
    const shift = 5 * (CHECKSUM_LENGTH - 1 - index);
    checksum.push((checksumValue >> shift) & 31);
  }

  return checksum;
}

export function bech32VerifyChecksum(hrp, data) {
  return polymod([...expandHrp(hrp), ...data]) === FINAL_CONSTANT;
}

export const bech32_create_checksum = bech32CreateChecksum;
export const bech32_verify_checksum = bech32VerifyChecksum;

